local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["da142e9f9c6fdb16"] = { "Buongiorno, Corbett. Ecco il tuo formaggio, fatto fresco stamattina! E come vanno le cose al tuo negozio?", "." },
  ["da153b0673709ca0"] = { "Krang Stonehoof domina il suo cerchio d'addestramento, nell'angolo sud-orientale del villaggio.", "." },
  ["da183fa001e1e60a"] = { "%s indica la brocca d'acqua posata sul bordo del pozzo.", "." },
  ["da1a6b9dac130250"] = { "Sei <terminato/terminata>.", "." },
  ["da1e1948081dfb25"] = { "Oh, amore mio! No! Non lasciarmi morire senza di te...", "." },
  ["da1e3d483e2cd962"] = { "No, {name}, non l'hai fatto. Non te ne faccio una colpa, però, perché la tua mente somiglia molto alla mia da giovane: impetuosa, ribelle e spesso priva di un solo pensiero coerente! Tratti che non posso più permettermi di mostrare.\n\nBasta lamenti. {race}, ho un compito per te; uno a cui potresti non sopravvivere.", "." },
  ["da25b36e5fcb6918"] = { "Dimmi la frase per la cassetta di sicurezza di Tirth.", "." },
  ["da40c86c2f7f8712"] = { "Che tu sia <benedetto/benedetta>, <confratello/sorella>. La nostra Sisterhood of Elune è un pilastro della società kaldorei da migliaia di anni.\n\nPrima della Grande Separazione, prima della Guerra degli Antichi, durante la Lunga Veglia, abbiamo guidato e curato il nostro popolo attraverso le tenebre. Tale è il nostro compito, e tale è ciò che esige l'impareggiabile Madre Luna.\n\nOra ci serve il tuo aiuto in una questione di grande importanza. La sorella Aquinne attende il tuo arrivo a Darnassus.", "." },
  ["da449a9a289aae96"] = { "Come promesso, {name}, ecco la tua ricetta! Ti aggiungo anche qualcosina in più per tutto il tuo impegno e la tua dedizione. Tanto, che me ne faccio di questi???", "." },
  ["da455ea7e731f858"] = { "Parla con Lawrence Shneider al Duncan's Textiles, dietro l'angolo a sinistra. Sa come trattare con i principianti.", "." },
  ["da458cf29080139e"] = { "Hai l'aria di <un/una> <uomo/donna> in cerca di conoscenza. Forse cerchi gli insegnamenti della forgia e del martello. Forse posso guidarti su quella strada. Ma solo dopo che avrai accettato gli spiriti e ascoltato il loro richiamo.", "." },
  ["da4b47ca6596fd86"] = { "OH NO, NON L'HAI FATTO! ORA SI FA SUL SERIO! <PH>", "." },
  ["da50f9a0e1c909cb"] = { "Verserò il tuo sangue, {class}!", "." },
  ["da5169b58ee90fdc"] = { "Ho perso il talismano, Falthir. Me ne serve uno nuovo.", "." },
  ["da60899a68deab00"] = { "{name}! Preparati ad affrontare la tua fine!", "." },
  ["da662b8c3ed4837f"] = { "Benvenut<o/a> all'⟦Camp Mojache=Accampamento Mojache⟧, <valoroso/valorosa> {class}. Come posso aiutarti quest'oggi?", "." },
  ["da6a198e03c2b582"] = { "La mia missione è compiuta. Potrei avere qualche rifornimento in più, se ti serve.", "." },
  ["da6dd7c84ebe1e41"] = { "Dimmi cosa vuoi, e fai in fretta.", "." },
  ["da7f898d3ef59593"] = { "Gorzeeki mi dice che gli hai portato tutto ciò che gli serve per la Bell of Dethmoora, la Wheel of the Black March e la Doomsday Candle.\n\nBen fatto, {name}! Ti manca poco per eseguire il tuo rituale e vincolare un maldestriero!", "." },
  ["da8d24dbfca586cc"] = { "La Luce sia con te, {class}. Come posso aiutarti?", "." },
  ["da90204f515612f7"] = { "Allora, ho trovato questa chiave delle catene...", "." },
  ["da907ff88243e94a"] = { "Salute, {class}: sono un ufficiale degli encomi e opero per conto di ⟦Thunder Bluff=Picco del Tuono⟧. Il mio compito è assistere gli avventurieri che hanno ricevuto Anelli d'Encomio dell'⟦Horde=Orda⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne dieci alla volta. Quando mi consegnerai gli anelli, registrerò le tue gesta nei nostri archivi. Così otterrai la riconoscenza di ⟦Thunder Bluff=Picco del Tuono⟧ per il tuo impegno e il tuo servizio.", "." },
  ["da99f8662d8b5854"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è scavato nelle montagne, oltre il ponte a est di Dun Baldar.\n\nAl momento è controllato dall'⟦Alliance=Alleanza⟧.", "." },
  ["da9f0ffa8889dd82"] = { "Aiuto!\n\nSe mi tiri fuori di qui, posso far saltare la porta che conduce al capo di ⟦Zul'Farrak=Zul'farrak⟧!", "." },
  ["daaa0a59904ead20"] = { "Ti do il benvenuto, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, mi farà piacere addestrarti.\n\nPresto verrà il momento in cui il richiamo del ⟦Emerald Dream=Sogno di Smeraldo⟧ si impadronirà di te. Andrai in letargo per molti anni e camminerai tra le forme più pure. Sarà lì, e allora, che si svolgerà il tuo addestramento finale.", "." },
  ["daab03fd650fd222"] = { "Sì? Certo che lavoro alla forgia. Cosa credi, che solo i nani valgano il loro peso in incudini? Va bene, fa' come ti pare. Va' a farti aiutare da un nano!", "." },
  ["dabfbae4c1e147ce"] = { "<Benvenuto/Benvenuta> nel paese del gusto!", "." },
  ["dac62edd5cb5e4ec"] = { "I miei preparativi sono pronti: mi servono solo i cuori di raptor.", "." },
  ["dac893fd0261506c"] = { "Scatenate la cavalleria!", "." },
  ["dac8e84126e74afb"] = { "Ho colpito il bersaglio per un pelo, stavolta. Mmm... forse devo correggere di nuovo verso destra.", "." },
  ["dacd03ce62b476bf"] = { "Possa io crogiolarmi nella tua ombra per sempre!", "." },
  ["dad15c096a741635"] = { "Vorrei volare a ⟦Rut'theran Village=Rut'theran⟧.", "." },
  ["dad30571769888dc"] = { "Un giorno sarò un bambino vero.", "." },
  ["dada4cc2f29dddfc"] = { "Prendilo! Questo affare probabilmente dà più problemi di quanto valga.", "." },
  ["dadb1df402413fcc"] = { "Aspetta, {name}! Creare una ricompensa di qualità così squisita richiede tempo.", "." },
  ["dadc3f253d7a1ea3"] = { "Raze dovere andare a casa ora. Ciao ciao, {race}.", "." },
  ["dadc4c6b58e63ffd"] = { "Se sei qui per mangiare, benvenut<o/a>! Non troverai cucina migliore in tutta ⟦Stormwind=Roccavento⟧... anzi, in tutta Azeroth!\n\nSe sei qui per altre faccende, ti prego di essere breve. Ho una dozzina di piatti in preparazione e devo badare a ognuno.", "." },
  ["dadf5582827764f7"] = { "I fili che tengono insieme gli abomini di Stratholme sono molto ricercati dagli artigiani: estremamente resistenti, quasi indistruttibili.", "." },
  ["dae2555bd5dd6e8d"] = { "Il druido Kal passa spesso il suo tempo presso il pozzo lunare di Dolanaar. Di certo potrà fornirti l'addestramento che ti serve.", "." },
  ["dae5130969d3a336"] = { "Per la barba di Thaurissan! Uccideteli!", "." },
  ["daedb2cf199e4571"] = { "Come il destino stabilì una vita fa a Karazhan, mostro, io vengo, e con me porto giustizia.", "." },
  ["daf55318be0d0070"] = { "Alt, {name}! Sto facendo la guardia a questi barili, quindi... guarda, ma non toccare!", "." },
  ["daf9d3e62c171776"] = { "Dottor Herbert Halsey in The Apothecarium dove noi nati. Lui può ricucire te meglio come noi.", "." },
})
